"""Helpers for validating and handling incoming API requests."""

from typing import Any


def _validate_request(data: Any, client_id: Any) -> None:
    """Validate the parts of a request required by the API handler.

    Validation happens before rate-limit accounting so malformed requests are
    rejected consistently and are never passed to ``process``.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not isinstance(client_id, str):
        raise TypeError("client_id must be a string")
    if not client_id.strip():
        raise ValueError("client_id must not be empty")


def handle_request(data: dict[str, Any], client_id: str) -> Any:
    """Validate, rate-limit, and process an incoming API request."""
    _validate_request(data, client_id)

    if not check_rate_limit(client_id):
        raise RuntimeError("rate limit exceeded")

    return process(data)

